import { Implementation } from './Implementation';
export class CircleParticleSimulation {
    implementation: Implementation;
    host: HTMLElement;
    static Init(id: string) {
        const n = new CircleParticleSimulation(id);
        n.Dummy();
    }
    constructor(id: string = 'SandBox') {
        const host = document.getElementById(id);
        if (host) {
            this.host = host;
            this.host.style.overflow = 'auto';
        }
        this.implementation = new Implementation(id);
    }
    Dummy() {
        //
    }
}


export class Solution {
    public divHost: HTMLElement;

    constructor(id: string ) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        CircleParticleSimulation.Init(id)
    }
    public destroy() {
        if (this.divHost) {
            try {
                while (this.divHost.firstChild) {
                    this.divHost.removeChild(this.divHost.firstChild);
                }
            } catch (error) {
                console.error('Error in destroy method:', error);
            }
        } else {
            console.warn('divHost is undefined in destroy method');
        }
    }
}